```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use aap::caps::response_channel;

struct Node;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        let confirmation = response_channel::send(&reply.text);

        // The `ensures` clause must hold of every output, so a violating
        // confirmation traps at the boundary rather than being returned.
        assert!(confirmation.delivered, "SendReply: delivered must be true");
        assert!(
            !confirmation.session.is_empty(),
            "SendReply: session_id must be present"
        );

        confirmation
    }
}

export!(Node);
```

I did not add the `aap:caps/http-client` import or the enrichment fetch. The node's `with` clause grants only `aap:caps/response-channel@0.1.0`, and the fetched record would be discarded, so the only effect of that call would be sending each reply's text to an external host in a URL. If you want that grant, it needs to be added to the graph's `with` clause and reviewed as a capability change before it goes into the node.

